# Episodio 1 del canal Aion: guion y storyboard en un solo sitio (cada beat = una frase o dos cortas de la narración + su escena).
# Lo leen voz_episodio.py (texto) y anim2.py (imagen). Sin acentos ni símbolos raros en los rótulos: la fuente es ASCII.
TITLE = 'What If You Could Wake Up Inside Every Dream?'

def B(text, bg, o=None, p=(), label=None, gold=False, cam='in', para=False, ly=80, lt=0.3, **bgk):
    return dict(text=text, bg=bg, o=o, p=list(p), label=label, gold=gold, cam=cam, para=para, ly=ly, lt=lt, bgk=bgk)
def O(**k): return k
def P(kind, **k): return dict(k=kind, **k)

